[workspace]
# The application resolves its helpers beside its executable. Include the Windows
# ActiveX host in development builds; release packaging filters it by platform.
default-members = [
    "crates/nyaterm-app",
    "crates/nyaterm-mcp",
    "crates/nyaterm-rdp-helper",
    "crates/nyaterm-activex-helper",
    "crates/nyaterm-vnc-helper",
]
members = [
    "crates/nyaterm-app",
    "crates/nyaterm-core",
    "crates/nyaterm-desktop",
    "crates/nyaterm-mcp",
    "crates/nyaterm-mcp-protocol",
    "crates/nyaterm-otp",
    "crates/nyaterm-plugin-api",
    "crates/nyaterm-plugin-host",
    "crates/nyaterm-rdp-helper",
    "crates/nyaterm-activex-helper",
    "crates/nyaterm-remote-desktop",
    "crates/nyaterm-store",
    "crates/nyaterm-sync",
    "crates/nyaterm-terminal",
    "crates/nyaterm-terminal-gpui",
    "crates/nyaterm-transport",
    "crates/nyaterm-ui",
    "crates/nyaterm-vnc-helper",
]
resolver = "3"
# `temp/` is untracked and holds local reference checkouts, including the
# sources that used to be vendored here, now under `temp/vendor/`. None of it is
# part of the build: every one of those dependencies comes from a pinned fork
# revision below. Editing anything under `temp/` has no effect on what is
# compiled. The exclude entry only stops cargo from claiming those manifests
# belong to this workspace, so they can still be built on their own.
exclude = ["temp", "examples/plugins/guests"]

[workspace.package]
version = "2.0.0"
edition = "2024"
authors = ["Kang"]
license = "Apache-2.0"
repository = "https://github.com/nyakang/nyaterm"

[workspace.dependencies]
automerge = "=0.12.0"
httpdate = "1.0"
aes-gcm = "0.11"
aes = { version = "0.8", features = ["zeroize"] }
cbc = "0.1"
pbkdf2 = "0.12"
sha3 = "0.10"
argon2 = { version = "0.5.3", features = ["zeroize"] }
alacritty_terminal = "0.26.1-dev"
anyhow = "1"
async-http-proxy = { version = "1.2.5", features = ["runtime-tokio", "basic-auth"] }
base64 = "0.22"
bytes = "1.7"
crypto_secretbox = "0.1"
digest = "0.11.0-rc.5"
dirs = "6"
encoding_rs = "0.8"
futures = "0.3"
same-file = "1"
tempfile = "3"
glob = "0.3.4"
gpui = { version = "=0.2.2", git = "https://github.com/nyakang/zed", rev = "8e5a53c0aa6ff991bdf2bcbb4e6049e2f4715658" }
gpui-base = { git = "https://github.com/nyakang/gpui-kit", rev = "c0ca15118df36f96675b9ce355daa5ca2444f285" }
gpui-kit = { git = "https://github.com/nyakang/gpui-kit", rev = "c0ca15118df36f96675b9ce355daa5ca2444f285" }
gpui_platform = { git = "https://github.com/nyakang/zed", rev = "8e5a53c0aa6ff991bdf2bcbb4e6049e2f4715658" }
# Pure-Rust, `#![forbid(unsafe)]` PDF rasterizer (MIT OR Apache-2.0). Pinned
# exactly: the crate is pre-1.0 and explicitly experimental, so a caret range
# could pull in a breaking 0.8 without review. `embed-fonts` bundles the 14
# permissively-licensed standard-font substitutes so previews of PDFs that rely
# on non-embedded base fonts still render without custom font loading.
hayro = { version = "=0.7.1", features = ["embed-fonts"] }
hex = "0.4"
hmac = "0.13"
ironrdp-input = "0.8.0"
jsonc-parser = { version = "0.34", features = ["serde"] }
keyring = { version = "3.6", features = [
    "apple-native",
    "windows-native",
    "sync-secret-service",
    "crypto-rust",
] }
log = "0.4.11"
md5 = "0.8"
nyaterm-core = { path = "crates/nyaterm-core" }
nyaterm-mcp-protocol = { path = "crates/nyaterm-mcp-protocol" }
nyaterm-desktop = { path = "crates/nyaterm-desktop" }
nyaterm-otp = { path = "crates/nyaterm-otp" }
nyaterm-plugin-api = { path = "crates/nyaterm-plugin-api" }
nyaterm-plugin-host = { path = "crates/nyaterm-plugin-host" }
nyaterm-remote-desktop = { path = "crates/nyaterm-remote-desktop" }
nyaterm-store = { path = "crates/nyaterm-store" }
nyaterm-sync = { path = "crates/nyaterm-sync" }
nyaterm-terminal = { path = "crates/nyaterm-terminal" }
nyaterm-terminal-gpui = { path = "crates/nyaterm-terminal-gpui" }
nyaterm-transport = { path = "crates/nyaterm-transport" }
nyaterm-ui = { path = "crates/nyaterm-ui" }
percent-encoding = "=2.3.2"
portable-pty = { git = "https://github.com/nyakang/portable-pty", rev = "1ececcf9a10437f2fe04d0756735cd0847219a26" }
quick-xml = "0.40"
rand = { version = "0.10", features = ["thread_rng"] }
redb = "4.1.0"
regex = "1.11.1"
rmcp = "=3.1.4"
rustls = { version = "0.23.43", default-features = false, features = ["aws_lc_rs", "std"] }
russh = { git = "https://github.com/nyakang/russh", rev = "3092e06cc827fc0f8d4c991280478f6e53c121a3", features = ["des", "dsa"] }
russh-sftp = { git = "https://github.com/nyakang/russh-sftp", rev = "b638b4896de6a0efd699e4c3833873221b3b3f01" }
rusty-leveldb = "4.0"
rust-embed = { version = "8.11", features = ["include-exclude", "debug-embed"] }
rust-i18n = "4.2"
schemars = "=1.2.2"
serialport = { version = "4", default-features = false }
serde = { version = "1", features = ["derive"] }
serde_json = { version = "1", features = ["raw_value"] }
semver = { version = "1", features = ["serde"] }
sha1 = { version = "0.11", features = ["oid"] }

{
  "name": "openterminal",
  "private": true,
  "workspaces": ["server", "web"],
  "overrides": {
    "qs": "^6.16.0"
  },
  "scripts": {
    "dev": "concurrently -n api,web -c yellow,cyan \"npm run dev -w server\" \"npm run dev -w web\"",
    "build": "npm run build -w server && npm run build -w web",
    "start": "concurrently -n api,web \"npm run start -w server\" \"npm run start -w web\"",
    "test": "npm run test -w server",
    "lint": "npm run lint -w web"
  },
  "devDependencies": {
    "concurrently": "^9.1.2"
  }
}

[patch.crates-io]
schemars = { git = "https://github.com/howardjohn/schemars", rev = "f3e45a59786debf49e67d6bd6d8dcffc004d39ff" }
http-serde = { git = "https://gitlab.com/howardjohn/http-serde", rev = "c2e482be0ddf029895ba72ef8749b9f94b388fc7" }
wiremock = { git = "https://github.com/howardjohn/wiremock-rs", rev = "79e5f488d8bc3bce2f7b397b5791b5caef5129e6" }
async-openai = { git = "https://github.com/howardjohn/async-openai", rev = "fa0cf6c879b0ce30658df604d76d0b42f27b134c" }
# Pending https://github.com/bldr-project/yaml-serde-edit/pull/1
yaml-serde-edit = { git = "https://github.com/howardjohn/yaml-serde-edit", rev = "683e137f6760f47bb0db3d124c211433a4819f54" }
# TODO: remove once https://github.com/goliajp/rust-tiktoken/pull/15 is released
tiktoken = { git = "https://github.com/howardjohn/rust-tiktoken", rev = "14ea59ef50aed1d2935bbce06d8811427b7b972f" }

[workspace]
resolver = "2"
members = [
    "crates/agentgateway",
    "crates/agentgateway-app",
    "crates/cel-fork/cel",
    "crates/cel-fork/cel-derive",
    "crates/celx",
    "crates/llm",
    "crates/pool",
    "crates/core",
    "crates/http",
    "crates/policy-core",
    "crates/policies/cors",
    "crates/hbone",
    "crates/htpasswd-verify-fork",
    "crates/protos",
    "crates/xds",
    "crates/xtask",
]
default-members = [
    "crates/agentgateway",
    "crates/agentgateway-app",
    "crates/cel-fork/cel",
    "crates/cel-fork/cel-derive",
    "crates/celx",
    "crates/llm",
    "crates/pool",
    "crates/core",
    "crates/http",
    "crates/policy-core",
    "crates/policies/cors",
    "crates/hbone",
    "crates/htpasswd-verify-fork",
    "crates/protos",
    "crates/xds",
]

[workspace.package]
version = "0.0.0" # We do not use this version
edition = "2024"
license = "Apache-2.0"
publish = false

[workspace.dependencies]
agent-core = { path = "crates/core" }
agent-celx = { path = "crates/celx" }
agent-hbone = { path = "crates/hbone" }
agent-http = { path = "crates/http" }
agent-llm = { path = "crates/llm" }
agent-policy = { path = "crates/policy-core" }
agent-policy-cors = { path = "crates/policies/cors" }
agent-pool = { path = "crates/pool" }
agent-xds = { path = "crates/xds" }
agentgateway = { path = "crates/agentgateway" }
cel = { path = "crates/cel-fork/cel" }
protos = { path = "crates/protos" }
atomic_float = { version = "1.1.0", features = ["serde"] }
anyhow = "1.0"
arc-swap = "1.9"
arcstr = { version = "1.2", features = ["serde"] }
assert_matches = "1.5.0"
async-openai = { version = "0.42", default-features = false, features = ["chat-completion-types", "decision-types", "moderation-types", "response-types", "realtime-types"] }
async-stream = "0.3"
async-trait = "0.1"
aws-config = { version = "1.8", default-features = false, features = ["default-https-client", "rt-tokio", "sso"] }
aws-credential-types = "1.2"
aws-sigv4 = "1.4"
aws-types = "1.3"
aws-smithy-eventstream = "0.61"
aws-smithy-runtime-api = { version = "1.19", features = ["client", "http-1x"] }
aws-smithy-types = "1.3"
aws-lc-rs = "1.18"
# SymCrypt backend: symcrypt 0.5.1 dynamic-links the system libsymcrypt by default (requires libsymcrypt installed).
symcrypt = "0.5.1"
rustls-symcrypt = { version = "0.2.3", features = ["chacha", "x25519"] }
axum = { version = "0.8", features = ["macros"] }
axum-core = "0.5"
axum-extra = { version = "0.12", features = ["json-lines", "typed-header"] }
multer = "3.0.0"
# Disable default features to avoid pulling in native-tls and requiring openssl
# TODO: allow default features if we ever add an openssl feature
azure_identity = { version = "1.0", default-features = false }
azure_core = { version = "1.0", default-features = false }
typespec_client_core = { default-features = false, version = "1.0" }
base64 = "0.23.0"
cookie = { version = "0.18", default-features = false }
bcrypt = "0.19"
bytes = { version = "1.11", features = ["serde"] }
chrono = { version = "0.4", features = ["serde"] }
clap = { version = "4.6", features = ["derive"] }
clocksource = "1.0"
crossbeam = "0.8"
dashmap = "6.2"
divan = "0.1"
durationfmt = "0.1"
go-parse-duration = "0.1"
flurry = "0.5.2"
fs-err = { version = "3.3", features = ["tokio"] }
futures = "0.3"
futures-channel = "0.3"
futures-core = "0.3"
futures-util = "0.3"
google-cloud-auth = { version = "1.16", default-features = false, features = [
    "idtoken",
    # Support the full ADC set; this one is opt in
    "gdch",
    # They use AWS-LC which is what we want so its fine. If they changed we would need to switch
    # To installing a global default which is annoying so prefer to do it this way.
    "default-rustls-provider",
] }
hashbrown = "0.17"
h2 = "0.4"
headers = "0.4"
hex = "0.4"
hickory-resolver = { version = "0.26", features = ["serde"] }
htpasswd-verify-fork = { path = "crates/htpasswd-verify-fork" }
httpdate = "1.0"
http = "1.4"
http-body = "1"
http-body-util = "0.1.3"
hyper = { version = "1.9", features = ["full"] }
hyper-util = { version = "0.1", features = ["full"] }
include_dir = "0.7"
